<script setup>
import { onMounted, reactive } from 'vue';import { useRouter } from 'vue-router';import { listNotifications,markAllRead,markRead } from '../../api/notification';import { session } from '../../utils/session';import { options,text,formatDate } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue'
const router=useRouter();const state=reactive({list:[],total:0,pageNum:1,pageSize:10,isRead:null,notificationType:'',loading:false});const load=async()=>{state.loading=true;try{const r=await listNotifications({pageNum:state.pageNum,pageSize:state.pageSize,isRead:state.isRead??undefined,notificationType:state.notificationType||undefined});state.list=r.data.list;state.total=r.data.total}finally{state.loading=false}}
const read=async(item)=>{if(!item.isRead){await markRead(item.id);item.isRead=1}if(item.businessType==='CASE'&&item.businessId)router.push(`/${session.user.role.toLowerCase()}/cases/${item.businessId}`);else if(item.businessType==='BILL')router.push(`/${session.user.role.toLowerCase()}/bills`)};const all=async()=>{await markAllRead();load()};onMounted(load)
</script>
<template><div class="page"><PageHeader title="消息中心" description="案件、官文、时限与费用动态"><el-button @click="all">全部已读</el-button></PageHeader><div class="toolbar"><div class="filters"><el-select v-model="state.isRead" placeholder="阅读状态" clearable @change="load"><el-option label="未读" :value="0"/><el-option label="已读" :value="1"/></el-select><el-select v-model="state.notificationType" placeholder="通知类型" clearable @change="load"><el-option v-for="o in options('notificationType')" :key="o.value" v-bind="o"/></el-select></div></div><div v-loading="state.loading" class="notification-list"><button v-for="n in state.list" :key="n.id" class="notification-card" :class="{unread:!n.isRead}" @click="read(n)"><span class="notification-dot"></span><div><div class="notification-title"><b>{{n.title}}</b><span>{{text('notificationType',n.notificationType)}}</span></div><p>{{n.content}}</p><time>{{formatDate(n.createTime)}}</time></div></button><el-empty v-if="!state.list.length" description="暂无消息"/></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/></div></template>
